3: export class ApiError extends Error {
4:   status: number;
5:   body: Record<string, unknown>;
6: 
7:   constructor(status: number, message: string, body: Record<string, unknown>) {
8:     super(message);
9:     this.name = 'ApiError';
10:     this.status = status;
11:     this.body = body;
12:   }
13: }
