100: /** Segment « déjà rangé » à afficher sur l'épars, ou null — le jumeau rangé
101:  *  (dupMatches, EPIC-028) n'est signalé que s'il est CONSULTABLE à droite sous
102:  *  le filtre sync-source actif : son dossier matche le terme (sémantique
103:  *  identique à l'arbre : sous-chaîne insensible à la casse sur les noms de
104:  *  dossiers), ou son nom de fichier en mode 📄 fichiers (auto-expansion).
105:  *  Sans filtre → null : la pastille n'a de sens qu'en contexte de rangement. */
106: export function twinUnderFilteredDir(
107:   sourceFullPath: string,
108:   term: string,
109:   filesMode: boolean,
110:   sourceFiles: Record<string, FileIndex>,
111: ): string | null {
112:   const t = term.trim().toLowerCase();
113:   if (!t) return null;
114:   const root = Object.keys(sourceFiles).find(r => sourceFullPath.startsWith(`${r}/`));
115:   if (!root) return null;
116:   const segments = sourceFullPath
117:     .slice(root.length + 1)
118:     .split('/')
119:     .filter(Boolean);
120:   const filename = segments.pop();
121:   if (!filename) return null;
122:   const dir = segments.join('/');
123:   if (filesMode && filename.toLowerCase().includes(t)) return dir ? `${dir}/${filename}` : filename;
124:   return dir.toLowerCase().includes(t) ? dir : null;
125: }

