124:     const pendingTracks = getPendingTracks(name);
125:     inPlaylistPaths = new Set(pendingTracks.map(t => t.fullPath));
126:   }
127: 
128:   const subDirs = Object.keys(node)
129:     .filter(k => k !== '__files__')
130:     .sort();
131:   for (const subName of subDirs) {
132:     const subFullPath = `${fullPath}/${subName}`;
133:     const subNode = node[subName] as TreeNode;
134:     const subFiles = (subNode.__files__ || []) as FileEntry[];
135:     const subExpanded = state.sourceExpanded.has(subFullPath);
136: 
137:     const dirEl = document.createElement('div');
138:     dirEl.className = `directory${subExpanded ? ' expanded' : ''}`;
139:     dirEl.dataset.dirpath = subFullPath;
140:     dirEl.dataset.focuspath = subFullPath;
141: 
142:     const nameSpan = document.createElement('span');
143:     nameSpan.textContent = subName;
144:     dirEl.appendChild(nameSpan);
145:     if (subFiles.length > 0) {
146:       const countSpan = document.createElement('span');
147:       countSpan.className = 'dir-count';
148:       countSpan.textContent = `(${subFiles.length})`;
149:       dirEl.appendChild(countSpan);
150:     }
151:     dirEl.onclick = () => {
152:       const cont = dirEl.closest(
153:         '#source-container, #playlist-source-container, #epars-container',
154:       ) as HTMLElement | null;
155:       if (cont) {
156:         focusItemByElement(cont, dirEl);
157:         // EPIC-052 : un clic ne fait jamais scroller le panneau activé.
158:         if (cont.id === 'epars-container') setActivePanel('epars', { silentScroll: true });
159:         else if (cont.id !== 'playlist-source-container') setActivePanel('source', { silentScroll: true });
160:       }
161:       toggle(subFullPath);
162:     };
163:     dirEl.oncontextmenu = (e: MouseEvent) => {
164:       e.preventDefault();
165:       showDirContextMenu(e.clientX, e.clientY, subFullPath);
166:     };
167:     dirEl.ondragover = (e: DragEvent) => {
168:       if (!e.dataTransfer?.types.includes('application/x-epars-copy')) return;
169:       e.preventDefault();
170:       dirEl.classList.add('drag-over');
171:     };
172:     dirEl.ondragleave = () => dirEl.classList.remove('drag-over');
173:     dirEl.ondrop = (e: DragEvent) => {
174:       e.preventDefault();
175:       dirEl.classList.remove('drag-over');
176:       const raw = e.dataTransfer?.getData('application/x-epars-copy');
177:       if (raw) {
178:         try {
179:           const { filename, eparDir } = JSON.parse(raw);
180:           doDragCopy(filename, eparDir, subFullPath);
181:         } catch (_) {
182:           /* invalid data */
183:         }
184:       }
185:     };
186:     childContainer.appendChild(dirEl);
187:     state.sourceNodeMap = new Map([...state.sourceNodeMap, [subFullPath, { node: subNode, baseDir }]]);
188: 
189:     if (subExpanded) {
190:       dirEl.appendChild(buildSourceChildren(subNode, subFullPath, baseDir, isFiltered, inPlaylistPaths, toggleFn));
191:     }
192:   }
193: 
194:   if (!isFiltered) {
195:     const status: FileStatus = inPlaylistPaths ? 'nouveau' : 'doublon';
196:     // EPIC-046 : 8ᵉ colonne « Style » — le fichier rangé DANS sa déclaration de
197:     // style (dossier). Sans elle, l'écriture du tag à la copie (EPIC-043) et
198:     // `g` sur un rangé étaient invisibles dans cette colonne.
199:     const fileTable = makeFileTable(true, true);
200:     const tbody = fileTable.querySelector('tbody');
201:     const lowerTerm = fileTerm.toLowerCase();
202:     const entries = (node.__files__ || []) as FileEntry[];
203:     // Mode fichiers (toggle 📄) : seuls les fichiers matchant le terme sont rendus.
204:     const visible = lowerTerm ? entries.filter(f => f.filename.toLowerCase().includes(lowerTerm)) : entries;
205:     for (const f of visible) {
206:       const fullFilePath = `${baseDir}/${f.relPath}`;
207:       const row = makeFileEl(
208:         f.filename,
209:         f.relPath,
210:         status,
211:         fullFilePath,
212:         f.year,
213:         f.duration,
214:         f.codec,
215:         undefined,
216:         startSourceRatingEdit,
217:         (fname, fpath) => openCueEditor({ filename: fname, fullPath: fpath }),
218:       );
219:       if (inPlaylistPaths?.has(fullFilePath)) {
220:         const label = row.querySelector('.file');
221:         if (label) label.classList.add('in-playlist');
222:       }
223:       insertSourceStyleCell(row, fullFilePath, { year: f.year, genre: f.genre });
224:       tbody?.appendChild(row);
225:     }
226:     if (tbody?.childElementCount) {
227:       childContainer.appendChild(fileTable);
228:     }
229:   }
230:   return childContainer;
231: }
