235: export function toggleSourceDir(
236:   dirPath: string,
237:   containerSelector = '#source-container',
238:   focusFirstChild = true,
239: ): void {
240:   const dirEl = document.querySelector(
241:     `${containerSelector} .directory[data-dirpath="${CSS.escape(dirPath)}"]`,
242:   ) as HTMLElement | null;
243:   if (!dirEl) return;
244: 
245:   const existingChildren = dirEl.querySelector('.children');
246:   if (existingChildren) {
247:     const nextExpanded = new Set(state.sourceExpanded);
248:     nextExpanded.delete(dirPath);
249:     state.sourceExpanded = nextExpanded;
250:     const nextManually = new Set(state.sourceManuallyExpanded);
251:     nextManually.delete(dirPath);
252:     state.sourceManuallyExpanded = nextManually;
253:     dirEl.classList.remove('expanded');
254:     existingChildren.remove();
255:   } else {
256:     state.sourceExpanded = new Set([...state.sourceExpanded, dirPath]);
257:     state.sourceManuallyExpanded = new Set([...state.sourceManuallyExpanded, dirPath]);
258:     dirEl.classList.add('expanded');
259:     const info = state.sourceNodeMap.get(dirPath);
260:     if (info) {
261:       const childrenEl = buildSourceChildren(
262:         info.node as TreeNode,
263:         dirPath,
264:         info.baseDir,
265:         // Fichiers masqués UNIQUEMENT si le filtre traque les fichiers
266:         // (toggle 📄 actif). En mode dossiers seuls (défaut), l'expansion —
267:         // manuelle ou auto — montre TOUS les fichiers du dossier : consulter
268:         // le contenu sous filtre est le moyen de vérifier un doublon.
269:         isFileFilter('sync-source') || isFileFilter('playlist-source'),
270:         undefined,
271:         undefined,
272:         fileTermForTrees(),
273:       );
274:       dirEl.appendChild(childrenEl);
275:       requestAnimationFrame(() => {
276:         // focusFirstChild=false (revealSourceDir post-copie) : ne pas voler la
277:         // sélection de l'utilisateur — la copie s'affiche, le focus reste.
278:         if (!focusFirstChild) return;
279:         const cont = dirEl.closest('#source-container, #playlist-source-container') as HTMLElement | null;
280:         const firstChild = dirEl.querySelector(
281:           '.children > .directory, .children > .file-table .file-row',
282:         ) as HTMLElement | null;
283:         if (cont && firstChild) focusItemByElement(cont, firstChild);
284:       });
285:     }
286:   }
287:   updateSourceHeaderCount();
288: }
