397: /** Rendu filtré de l'arbre, paramétré par scope (sync-source, playlist-source).
398:  *  Renvoie le nombre de dossiers racine visibles. */
399: export function renderFilteredSource(container: HTMLElement, allTrees: TreeAndDir[], scope: string): number {
400:   let visibleCount = 0;
401:   const term = getFilterTerm(scope).toLowerCase();
402:   const filesMode = isFileFilter(scope);
403:   for (const { tree, dirPath } of allTrees) {
404:     const dirNames = Object.keys(tree)
405:       .filter(k => k !== '__files__')
406:       .sort();
407:     for (const name of dirNames) {
408:       const node = tree[name] as TreeNode;
409:       if (
410:         !name.toLowerCase().includes(term) &&
411:         !dirHasMatchingDescendant(node, term) &&
412:         !(filesMode && dirHasMatchingFile(node, term))
413:       )
414:         continue;
415:       visibleCount++;
416:       renderFilteredDirNode(node, container, dirPath, name, scope);
417:     }
418:   }
419:   return visibleCount;
420: }
