422: function renderFilteredDirNode(
423:   node: TreeNode,
424:   container: HTMLElement,
425:   basePath: string,
426:   name: string,
427:   scope: string,
428: ): void {
429:   const term = getFilterTerm(scope).toLowerCase();
430:   const filesMode = isFileFilter(scope);
431:   const fullPath = `${basePath}/${name}`;
432:   const dirMatch = dirHasMatchingDescendant(node, term);
433:   const fileMatch = filesMode && dirHasMatchingFile(node, term);
434:   if (!name.toLowerCase().includes(term) && !dirMatch && !fileMatch) return;
435: 
436:   const manualExpand = state.sourceExpanded.has(fullPath);
437:   const isExpanded = dirMatch || fileMatch || manualExpand;
438:   const files = (node.__files__ || []) as FileEntry[];
439: 
440:   const dirEl = document.createElement('div');
441:   dirEl.className = `directory${isExpanded ? ' expanded' : ''}`;
442:   dirEl.dataset.dirpath = fullPath;
443:   dirEl.dataset.focuspath = fullPath;
444: 
445:   const nameSpan = document.createElement('span');
446:   nameSpan.textContent = name;
447:   dirEl.appendChild(nameSpan);
448:   if (files.length > 0) {
449:     const countSpan = document.createElement('span');
450:     countSpan.className = 'dir-count';
451:     countSpan.textContent = `(${files.length})`;
452:     dirEl.appendChild(countSpan);
453:   }
454:   dirEl.onclick = () => {
455:     const cont = dirEl.closest('#source-container') as HTMLElement | null;
456:     if (cont) {
457:       focusItemByElement(cont, dirEl);
458:       setActivePanel('source', { silentScroll: true }); // EPIC-052 : clic = pas de scroll
459:     }
460:     toggleSourceDir(fullPath);
461:   };
462:   dirEl.oncontextmenu = (e: MouseEvent) => {
463:     e.preventDefault();
464:     showDirContextMenu(e.clientX, e.clientY, fullPath);
465:   };
466:   dirEl.ondragover = (e: DragEvent) => {
467:     if (!e.dataTransfer?.types.includes('application/x-epars-copy')) return;
468:     e.preventDefault();
469:     dirEl.classList.add('drag-over');
470:   };
471:   dirEl.ondragleave = () => dirEl.classList.remove('drag-over');
472:   dirEl.ondrop = (e: DragEvent) => {
473:     e.preventDefault();
474:     dirEl.classList.remove('drag-over');
475:     const raw = e.dataTransfer?.getData('application/x-epars-copy');
476:     if (raw) {
477:       try {
478:         const { filename, eparDir } = JSON.parse(raw);
479:         doDragCopy(filename, eparDir, fullPath);
480:       } catch (_) {
481:         /* invalid data */
482:       }
483:     }
484:   };
485:   container.appendChild(dirEl);
486:   state.sourceNodeMap = new Map([...state.sourceNodeMap, [fullPath, { node, baseDir: basePath }]]);
487: 
488:   if (isExpanded) {
489:     // Mode fichiers ON : auto-étendu MAIS table rendue, filtrée au terme
490:     // (le fichier cherché est visible). Mode dossiers : contenu COMPLET —
491:     // la vérification de doublon exige de voir tout ce que le dossier contient.
492:     dirEl.appendChild(
493:       buildSourceChildren(node, fullPath, basePath, false, undefined, undefined, filesMode ? term : ''),
494:     );
495:   }
496: }
