514: function renderExtraDirs(container: HTMLElement, allTrees: TreeAndDir[]): void {
515:   for (const dirPath of state.sourceExtraDirs) {
516:     let existsAsScanned = false;
517:     for (const { tree, dirPath: base } of allTrees) {
518:       if (dirPath === base) {
519:         existsAsScanned = true;
520:         break;
521:       }
522:       if (dirPath.startsWith(`${base}/`) && dirExistsInTree(tree, dirPath.slice(base.length + 1))) {
523:         existsAsScanned = true;
524:         break;
525:       }
526:     }
527:     if (existsAsScanned) continue;
528:     const name = dirPath.split('/').pop() || dirPath;
529:     const dirEl = document.createElement('div');
530:     dirEl.className = 'directory';
531:     dirEl.dataset.dirpath = dirPath;
532:     dirEl.dataset.focuspath = dirPath;
533:     dirEl.dataset.extra = '1';
534:     const nameSpan = document.createElement('span');
535:     nameSpan.textContent = name;
536:     dirEl.appendChild(nameSpan);
537:     const countSpan = document.createElement('span');
538:     countSpan.className = 'dir-count';
539:     countSpan.textContent = '(vide)';
540:     dirEl.appendChild(countSpan);
541:     dirEl.onclick = () => {
542:       const cont = dirEl.closest('#source-container, #playlist-source-container') as HTMLElement | null;
543:       if (cont) {
544:         focusItemByElement(cont, dirEl);
545:         // EPIC-052 : un clic ne fait jamais scroller le panneau activé.
546:         if (cont.id !== 'playlist-source-container') setActivePanel('source', { silentScroll: true });
547:       }
548:     };
549:     dirEl.oncontextmenu = (e: MouseEvent) => {
550:       e.preventDefault();
551:       showDirContextMenu(e.clientX, e.clientY, dirPath);
552:     };
553:     container.appendChild(dirEl);
554:   }
555: }
