613: // ── Main render ───────────────────────────────────────────────────────────
614: 
615: export function renderSource(): void {
616:   const container = document.getElementById('source-container');
617:   if (!container) return;
618:   const restore = beginRender(container); // EPIC-036 : wipe + save/restore scroll centralisés
619:   state.sourceNodeMap = new Map();
620: 
621:   // EPIC-030 : chip de filtre persistant (slot dédié hors du DOM effacé,
622:   // mémorisé scope 'sync-source') — la saisie survit aux re-renders.
623:   ensureFilterChip(container, {
624:     scope: 'sync-source',
625:     placeholder: 'Filtrer dossiers + fichiers…',
626:     onChange: renderSource,
627:     onBlur: () => revalidateFocus(),
628:     tree: true,
629:   });
630: 
631:   // Pastilles « déjà rangé » de l'épars : leur visibilité dépend du filtre
632:   // source — si le panneau gauche est rendu, le rafraîchir (les pastilles
633:   // périmées suivraient sinon un changement de terme du chip droit).
634:   const eparsContainer = document.getElementById('epars-container');
635:   if (eparsContainer && !eparsContainer.classList.contains('hidden')) {
636:     renderEpars();
637:     // Le rebuild efface .focused : réapplique la sélection épars persistée
638:     // (et le twin-hint associé) — rien si aucune sélection.
639:     if (state.eparsFocusPath) focusItemByPath(eparsContainer, state.eparsFocusPath);
640:   }
641: 
642:   // EPIC-053 : le rebuild ci-dessus efface AUSSI .focused de la colonne
643:   // source (chaque copie re-rend le panneau via sourceFiles:changed). Sans
644:   // restauration, le focus du dossier de droite DISPARAISSAIT — Tab repartait
645:   // du premier dossier et ↑↓ ne se souvenait plus de la destination : le
