41: /**
42:  * Match AND de tokens : chaque token doit matcher au moins un champ.
43:  *
44:  * Deux régimes :
45:  *  - token NON year-like (texte, `202`, `_schranz`…) : sous-chaîne sur
46:  *    l'ensemble nom + année + codec + sous-dossier + genre (historique intact) ;
47:  *  - token year-like (`1993`, `2020`…) : l'ANNÉE d'abord et exactement, puis le
48:  *    NOM de fichier (texte explicite), puis le sous-dossier — mais uniquement
49:  *    si le fichier n'a PAS d'année (fichier non taggé dans un dossier daté).
50:  *    Le sous-dossier ne peut donc plus faire mentir le filtre par année
51:  *    (échappatoire pour retrouver un dossier daté : préfixe non year-like,
52:  *    ex. « 2020_02 »).
53:  */
54: export function matchesTokens(foldedTerm: string, subject: FilterSubject): boolean {
55:   const foldedName = foldText(subject.name);
56:   const foldedYear = subject.year ? foldText(subject.year) : '';
57:   const foldedCodec = subject.codec ? foldText(subject.codec) : '';
58:   const foldedPath = subject.path ? foldText(subject.path) : '';
59:   const foldedGenre = subject.genre ? foldText(subject.genre) : '';
60:   const haystack = `${foldedName} ${foldedYear} ${foldedCodec} ${foldedPath} ${foldedGenre}`.trim();
