64:     .filter(t => t.length > 0)
65:     .every(token => {
66:       if (!isYearLike(token)) return haystack.includes(token);
67:       if (foldedYear === token) return true;
68:       if (foldedName.includes(token)) return true;
69:       if (!foldedYear && foldedPath.includes(token)) return true;
70:       return false;
